#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, k;
    if (!(cin >> n >> k)) return 0;

    vector<vector<int>> adj(n + 1);
    for (int i = 0; i < n - 1; ++i) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    if (k >= n) {
        cout << 0 << "\n";
        return 0;
    }

    // BFS para determinar a ordem de pós-ordem e os pais
    vector<int> order;
    order.reserve(n);
    vector<int> parent(n + 1, 0);
    vector<bool> visited(n + 1, false);

    order.push_back(1);
    visited[1] = true;

    int head = 0;
    while (head < (int)order.size()) {
        int u = order[head++];
        for (int v : adj[u]) {
            if (!visited[v]) {
                visited[v] = true;
                parent[v] = u;
                order.push_back(v);
            }
        }
    }

    auto check = [&](int R) -> bool {
        vector<int> max_uncovered(n + 1, 0);
        vector<int> max_cover(n + 1, -1);
        int radars = 0;

        for (int i = n - 1; i >= 0; --i) {
            int u = order[i];

            if (max_cover[u] >= max_uncovered[u]) {
                max_uncovered[u] = -1;
            }

            if (max_uncovered[u] == R) {
                radars++;
                max_cover[u] = R;
                max_uncovered[u] = -1;
            }

            int p = parent[u];
            if (p != 0) {
                if (max_uncovered[u] >= 0) {
                    max_uncovered[p] = max(max_uncovered[p], max_uncovered[u] + 1);
                }
                if (max_cover[u] > 0) {
                    max_cover[p] = max(max_cover[p], max_cover[u] - 1);
                }
            }
        }

        if (max_uncovered[1] >= 0) {
            radars++;
        }

        return radars <= k;
    };

    int low = 0, high = n, ans = n;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (check(mid)) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }

    cout << ans << "\n";

    return 0;
}
